    ('tse-2026-90002543556', 'c42bd3e6-1036-4da1-a78d-5b6e468bd6e8'::uuid, 2, 'https://comunicaapi.pje.jus.br/api/v1/comunicacao?itensPorPagina=100&numeroProcesso=07158438620238070001', 'revisao_em=2026-09-28; identidade=id-oficial; identidade_urls=https://cdn.tse.jus.br/estatistica/sead/odsele/consulta_cand/consulta_cand_2026.zip; urls_consultadas=https://comunicaapi.pje.jus.br/api/v1/comunicacao?itensPorPagina=100&numeroProcesso=07158438620238070001,https://comunicaapi.pje.jus.br/api/v1/comunicacao?itensPorPagina=100&numeroProcesso=52789791920238090051; detalhe=2 processo(s) com número CNJ, contexto oficial de identidade e parte na ação; revisão editorial em 28/09/2026')
  ) SELECT count(*) INTO n FROM public.coleta_log q LEFT JOIN e
    ON e.slug = q.alvo AND e.candidato_id = q.candidato_id
  WHERE q.execucao = 'migration:20260928010000' AND q.fonte = 'processos-curadoria' AND q.escopo = 'candidato'
    AND (e.slug IS NULL OR q.resultado IS DISTINCT FROM 'encontrado'
      OR q.volume IS DISTINCT FROM e.volume
      OR q.detalhe IS DISTINCT FROM e.detalhe
      OR q.url IS DISTINCT FROM e.url);
  IF n <> 0 THEN RAISE EXCEPTION 'rollback processos: % recibos divergentes; preservar revisao posterior', n; END IF;
END $$;

